#pragma once
#include <cuda_runtime.h>
#include <cuda_mathdx.h>

constexpr int kN = 16;

// y[b] = forward DFT of x[b] (length 16), for b in [0, batch). Asynchronous on `stream`.
void solve(const float2* x, float2* y, int batch, cudaStream_t stream) {
    // Launch a kernel to perform the FFTs
    dim3 threadsPerBlock(32, 1);
    dim3 blocksPerGrid((batch + threadsPerBlock.x - 1) / threadsPerBlock.x, 1);

    // Launch the kernel
    fft_kernel<<<blocksPerGrid, threadsPerBlock, 0, stream>>>(x, y, batch);
}

// Kernel to perform the FFTs
__global__ void fft_kernel(const float2* x, float2* y, int batch) {
    int b = blockIdx.x * blockDim.x + threadIdx.x;
    if (b >= batch) return;

    // Get the input and output pointers for this batch
    const float2* x_b = x + b * kN;
    float2* y_b = y + b * kN;

    // Perform the FFT using cuFFT
    cufftHandle plan;
    cufftPlan1d(&plan, kN, CUFFT_C2C, 1);
    cufftExecC2C(plan, (cufftComplex*)x_b, (cufftComplex*)y_b, CUFFT_FORWARD);
    cufftDestroy(plan);
}

