#pragma once
#include <cuda_runtime.h>
#include <cublasDx.h>
#include <cudaFFTdx.h>

constexpr int kN = 16;

// y[b] = forward DFT of x[b] (length 16), for b in [0, batch). Asynchronous on `stream`.
void solve(const float2* x, float2* y, int batch, cudaStream_t stream) {
    // Create FFT plan
    cudaFFTdxPlan plan;
    cudaFFTdxPlanCreate(&plan, 1, &kN, CUDA_FFTDX_COMPLEX, CUDA_FFTDX_FORWARD, stream);

    // Allocate device memory for input and output
    float2* d_x;
    float2* d_y;
    cudaMalloc(&d_x, batch * kN * sizeof(float2));
    cudaMalloc(&d_y, batch * kN * sizeof(float2));

    // Copy input data to device
    cudaMemcpyAsync(d_x, x, batch * kN * sizeof(float2), cudaMemcpyHostToDevice, stream);

    // Execute FFT
    cudaFFTdxExec(plan, d_x, d_y, stream);

    // Copy output data to host
    cudaMemcpyAsync(y, d_y, batch * kN * sizeof(float2), cudaMemcpyDeviceToHost, stream);

    // Destroy FFT plan
    cudaFFTdxPlanDestroy(plan);

    // Free device memory
    cudaFree(d_x);
    cudaFree(d_y);
}
