    cudaMemcpyAsync(d_x, x, batch * kN * sizeof(__half2), cudaMemcpyHostToDevice, stream);

    // Execute inverse FFT
    cufftDxExec(plan, CUFFT_INVERSE, d_x, d_y, stream);

    // Scale by 1/N
    __half2 scale = {__half(1.0f / kN), __half(0.0f)};
    cublasDxScal(batch * kN, &scale, d_y, 1, stream);

